{
  "static": {},
  "time": "",
  "volatile": [],
  "responseSummary": [],
  "func": [
    {
      "func_name": "initiate_incursion",
      "func_body": "if (!state.static.timelines || !state.static.active_incursions || !state.static.shipgirls || !state.dtime || state.dtime <= 0) return;
if (state.static.victory) return;
if (state.static.shipgirls.some(sg => sg.lust > 500)) return;

const MS_PER_DAY = 86400000;
const dtimeInDays = state.dtime / MS_PER_DAY;

for (const timelineId in state.static.timelines) {
  const timeline = state.static.timelines[timelineId];

  const isAlreadyAttacked = state.static.active_incursions.some(inc => inc.target_id === timeline.id);
  if (isAlreadyAttacked) {
    continue;
  }

  const dangerLevel = timeline.defense ? (timeline.defense.danger_level || 0) : 0;
  const attackProbability = (dangerLevel / 100.0) * dtimeInDays;

  if (Math.random() <= attackProbability) {
    const attackers = ['被同化的塞壬部队', '凝视者', '星之兽', '镜像舰娘', '纳米体舰队', 'X化身'];
    const attacker_type = attackers[Math.floor(Math.random() * attackers.length)];

    let offensive_index = Math.floor(Math.random() * 901) + 100; // Random integer between 100 and 1000
    if (attacker_type === 'X化身') {
      offensive_index = 1000;
    }

    const countdown = Math.floor(Math.random() * 91) + 10; // Random integer between 10 and 100

    const newIncursion = {
      attacker_type: attacker_type,
      target_id: timeline.id,
      offensive_index: offensive_index,
      countdown: countdown
    };

    state.static.active_incursions.push(newIncursion);
    console.log(`[Incursion Alert] A new incursion by ${attacker_type} has started, targeting ${timeline.name} (${timeline.id}).`);

    break; 
  }
}",
      "periodic": true,
      "order": "last",
      "sequence": 40,
      "func_params": []
    },{
      "func_name": "update_incursions",
      "func_body": "if (!state.dtime || state.dtime <= 0 || !state.static.active_incursions || state.static.active_incursions.length === 0) return;

const MS_PER_DAY = 86400000;
const dtimeInDays = state.dtime / MS_PER_DAY;
const lostTimelineIds = [];

for (let i = state.static.active_incursions.length - 1; i >= 0; i--) {
  const incursion = state.static.active_incursions[i];
  incursion.countdown -= dtimeInDays;

  if (incursion.countdown <= 0) {
    const lostTimelineId = incursion.target_id;
    const lostTimeline = state.static.timelines[lostTimelineId];

    if (lostTimeline) {
      console.log(`[Timeline Lost] The incursion by ${incursion.attacker_type} against ${lostTimeline.name} has succeeded. Countdown reached zero.`);
      lostTimelineIds.push(lostTimelineId);

      const retreatLocations = lostTimeline.connections?.exiting_this;
      let retreatTargetId = null;

      if (retreatLocations && retreatLocations.length > 0) {
        retreatTargetId = retreatLocations[0]; // Retreat to the first available connection
        const retreatTargetName = state.static.timelines[retreatTargetId]?.name || 'an adjacent timeline';
        console.log(`[Emergency Evacuation] All units at ${lostTimeline.name} are retreating to ${retreatTargetName}.`);

        // 1. Move all shipgirls from the lost timeline
        state.static.shipgirls.forEach(sg => {
          if (sg.location_timeline_id === lostTimelineId) {
            sg.location_timeline_id = retreatTargetId;
          }
        });

        // Move player as well
        if (state.static.player.location_timeline_id === lostTimelineId) {
          state.static.player.location_timeline_id = retreatTargetId;
        }
      } else {
        console.log(`[Catastrophic Loss] No escape route from ${lostTimeline.name}. All units stationed there are considered lost.`);
        // If no retreat path, units are effectively lost with the timeline.
      }
    }
    // Remove the completed incursion
    state.static.active_incursions.splice(i, 1);
  }
}

if (lostTimelineIds.length > 0) {
  // 2. Delete the lost timelines using lodash
  state.static.timelines = _.omit(state.static.timelines, lostTimelineIds);

  // Clean up connections in remaining timelines
  for (const timelineId in state.static.timelines) {
    const timeline = state.static.timelines[timelineId];
    if (timeline.connections) {
      if (timeline.connections.into_this) {
        timeline.connections.into_this = _.difference(timeline.connections.into_this, lostTimelineIds);
      }
      if (timeline.connections.exiting_this) {
        timeline.connections.exiting_this = _.difference(timeline.connections.exiting_this, lostTimelineIds);
      }
    }
  }
}",
      "periodic": true,
      "order": "first",
      "sequence": 10,
      "func_params": []
    },{
      "func_name": "sanitize_state",
      "func_body": "if (!state.static) return;

// Part 1: Sanitize negative numbers recursively
let normalizedCount = 0;
const normalizeNumbers = (obj) => {
  if (!obj || typeof obj !== 'object') return;
  Object.keys(obj).forEach(key => {
    const value = obj[key];
    if (typeof value === 'number' && value < 0) {
      obj[key] = 0;
      normalizedCount++;
    } else if (value && typeof value === 'object') {
      // Recurse into nested objects and arrays
      normalizeNumbers(value);
    }
  });
};
normalizeNumbers(state.static);
if (normalizedCount > 0) {
  console.log(`[State Sanitization] Normalized ${normalizedCount} negative numerical value(s) to 0.`);
}

// Part 2: Sanitize timeline connections
if (state.static.timelines) {
  const validTimelineIds = new Set(Object.keys(state.static.timelines));
  let removedLinksCount = 0;

  for (const timelineId in state.static.timelines) {
    const timeline = state.static.timelines[timelineId];
    if (timeline.connections) {
      if (Array.isArray(timeline.connections.into_this)) {
        const originalCount = timeline.connections.into_this.length;
        timeline.connections.into_this = timeline.connections.into_this.filter(id => validTimelineIds.has(id));
        removedLinksCount += originalCount - timeline.connections.into_this.length;
      }
      if (Array.isArray(timeline.connections.exiting_this)) {
        const originalCount = timeline.connections.exiting_this.length;
        timeline.connections.exiting_this = timeline.connections.exiting_this.filter(id => validTimelineIds.has(id));
        removedLinksCount += originalCount - timeline.connections.exiting_this.length;
      }
    }
  }

  if (removedLinksCount > 0) {
    console.log(`[State Sanitization] Removed ${removedLinksCount} invalid timeline connection(s).`);
  }
}",
      "periodic": true,
      "order": "last",
      "sequence": 99,
      "func_params": []
    }

  ]
}

